document.addEventListener("DOMContentLoaded",(()=>{const t=document.getElementById("url-form"),e=document.getElementById("url-input"),n=document.getElementById("web-frame"),o=document.getElementById("error");t.addEventListener("submit",(t=>{let d;t.preventDefault();try{d=new URL(e.value)}catch{return void(o.textContent="Escribe una URL válida.")}/^https?:$/.test(d.protocol)?(o.textContent="",n.src=d.href):o.textContent="La URL debe comenzar con http:// o https://."}))}));